<main class="page-content"><h1>Clases particulares</h1><div class="card"><h2>Monitores</h2><form method="post"><input type="hidden" name="admin_action" value="monitor"><input name="nombre" placeholder="Nombre" required><input name="email" placeholder="Email"><label><input type="checkbox" name="activo" checked> Activo</label><button class="button">Agregar monitor</button></form><?php foreach($monitores as $m):?><p><?=e($m['nombre'])?> — <?=((int)$m['activo'])?'Activo':'Inactivo'?></p><?php endforeach;?></div><div class="card"><h2>Disponibilidad</h2><form method="post"><input type="hidden" name="admin_action" value="availability"><select name="monitor_id"><option value="0">Todos</option><?php foreach($monitores as $m):?><option value="<?=$m['id']?>"><?=e($m['nombre'])?></option><?php endforeach;?></select><select name="dia_semana"><option value="6">Sábado</option><option value="0">Domingo</option></select><input type="time" name="hora_inicio" value="09:00"><input type="time" name="hora_fin" value="14:00"><button class="button">Guardar horario</button></form><form method="post"><input type="hidden" name="admin_action" value="generate"><input type="date" name="desde" value="<?=date('Y-m-d')?>"><input type="date" name="hasta" value="<?=date('Y-m-d',strtotime('+30 days'))?>"><button class="button">Generar bloques</button></form><?php foreach($reglas as $r):?><p><?=e($r['monitor']??'Todos')?> · <?=e($r['hora_inicio'])?>–<?=e($r['hora_fin'])?></p><?php endforeach;?></div><div class="card"><h2>Medios de pago</h2><?php foreach($medios as $p):?><p><?=e($p['nombre'])?> · <?=e((string)$p['porcentaje'])?>%</p><?php endforeach;?></div></main>
<?php if(!empty($transferencias)): ?><div class="card"><h2>Transferencias pendientes</h2><?php foreach($transferencias as $t): ?><p>Reserva #<?=e((string)$t['reserva_id'])?> · <?=e($t['cliente'])?> · $<?=number_format((float)$t['charged_amount'],0,',','.')?> · <?=e($t['status'])?> <?php if($t['status']==='pending'): ?><form method="post" style="display:inline"><input type="hidden" name="admin_action" value="validate_transfer"><input type="hidden" name="pago_id" value="<?=$t['id']?>"><button class="button">Validar pago</button></form><?php endif; ?></p><?php endforeach; ?></div><?php endif; ?>